\boxed{ 
 x_i^{(\lambda)}=
 \begin{cases}
 \dfrac{x_i^{\lambda}-1}{\lambda}, & \lambda \neq 0,
[10pt]
 \ln(x_i), & \lambda = 0.
 \end{cases} }

\frac{x^{\lambda}-1}{\lambda}
 =\frac{\lambda\ln x+\tfrac{\lambda^2\ln^2 x}{2}+\cdots}{\lambda}
 =\ln x+\frac{\lambda\ln^{2}x}{2}+\cdots
 \xrightarrow[\lambda\to0]{} \ln x .
